import { useState } from "react";
import type { Product } from "../types";
import { formatPrice } from "../lib/format";

type ProductCardProps = {
  product: Product;
  onAddToCart: (id: string) => Promise<void>;
};

export function ProductCard({ product, onAddToCart }: ProductCardProps) {
  const [adding, setAdding] = useState(false);

  async function handleAdd() {
    setAdding(true);
    try {
      await onAddToCart(product.id);
    } finally {
      setAdding(false);
    }
  }

  return (
    <article className="group flex flex-col rounded-xl bg-white">
      <img
        src={product.imageUrl}
        alt={product.name}
        className="aspect-square rounded-t-xl object-cover"
      />
      <div className="flex flex-1 flex-col gap-2 p-4">
        <h3 className="text-sm font-medium">{product.name}</h3>
        <p className="text-lg font-semibold">
          {formatPrice(product.price)}
        </p>
        <button
          type="button"
          onClick={handleAdd}
          disabled={adding}
          className="mt-auto rounded-lg bg-zinc-900 py-2 text-white"
        >
          {adding ? "Adding…" : "Add to cart"}
        </button>
      </div>
    </article>
  );
}

export type Product = {
  id: string;
  name: string;
  imageUrl: string;
  /** Price in cents. */
  price: number;
  /** The price before a markdown, in cents; absent when not on sale. */
  compareAtPrice?: number;
};

const usd = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
});

/** Formats an amount in cents, e.g. `$24.00`. */
export function formatPrice(cents: number): string {
  return usd.format(cents / 100);
}

/** Whole percent saved against `compareAt`, rounded down; 0 when not on sale. */
export function percentOff(price: number, compareAt?: number): number {
  if (compareAt === undefined || compareAt <= price) return 0;
  return Math.floor(((compareAt - price) / compareAt) * 100);
}

import { describe, expect, it } from "vitest";
import { formatPrice, percentOff } from "./format";

describe("formatPrice", () => {
  it("formats cents as dollars", () => {
    expect(formatPrice(2400)).toBe("$24.00");
  });
});

describe("percentOff", () => {
  it("rounds the saving down", () => {
    expect(percentOff(2999, 3999)).toBe(25);
  });

  it("is 0 unless the compare-at price is higher", () => {
    expect(percentOff(2400, 2400)).toBe(0);
    expect(percentOff(2400)).toBe(0);
  });
});

import { useState } from "react";
import type { Product } from "../types";
import { formatPrice, percentOff } from "../lib/format";

type ProductCardProps = {
  product: Product;
  onAddToCart: (id: string) => Promise<void>;
  /** Shows the "−25%" badge on discounted products. */
  showDiscount?: boolean;
};

export function ProductCard({
  product,
  onAddToCart,
  showDiscount = true,
}: ProductCardProps) {
  const [adding, setAdding] = useState(false);
  const discount = percentOff(product.price, product.compareAtPrice);

  async function handleAdd() {
    setAdding(true);
    try {
      await onAddToCart(product.id);
    } finally {
      setAdding(false);
    }
  }

  return (
    <article className="group relative flex flex-col rounded-xl bg-white">
      {showDiscount && discount > 0 && (
        <span className="absolute top-3 left-3 rounded-full bg-rose-600 px-2">
          −{discount}%
        </span>
      )}
      <img
        src={product.imageUrl}
        alt={product.name}
        className="aspect-square rounded-t-xl object-cover"
      />
      <div className="flex flex-1 flex-col gap-2 p-4">
        <h3 className="text-sm font-medium">{product.name}</h3>
        <p className="flex items-baseline gap-2 text-lg font-semibold">
          {formatPrice(product.price)}
